  "heroglyph.flow.dogCharacter.slide.guardian.desc": "현관문을 저승의 문처럼 지켜요. 일단 짖고, 질문은 절대 안 해요.",
  "heroglyph.flow.dogCharacter.slide.player.desc": "공 한 번만 더 던져 주면 영혼도 팔아요. 최고의 기쁨: 최애 장난감.",
  "heroglyph.flow.dogCharacter.slide.energizer.desc": "끄는 스위치 없음. 배터리 필요 없음. 가장 많이 듣는 질문: 이 개, 무슨 약 먹었어요?",
