  "heroglyph.flow.dogCharacter.slide.waterlover.desc": "개에는 두 종류가 있어요 — 그중 하나는 물고기로 착각할 수 있죠. 젖은 털: 행복 100%.",
  "heroglyph.flow.dogCharacter.slide.gourmet.desc": "먹는 게 사명이에요. 전력투구, 망설임 제로 — 당신이 남긴 것까지 먹어 치워요.",
  "heroglyph.flow.dogCharacter.slide.lover.desc": "세상에 낯선 사람이란 없어요. 집배원을 오래전 헤어진 소울메이트처럼 맞이해요. 매번.",
  "heroglyph.flow.dogCharacter.slide.chiller.desc": "아무것도 하지 않는 고대의 기술을 우아하게 터득했어요.",
