  "about.origin.skip": "건너뛰기",
  "about.crawl.intro": "10년 전, 유럽 중심부의 한 보호소에서…",
  "about.crawl.episode": "에피소드 I",
  "about.crawl.faith": "새로운 믿음",
  "about.crawl.p1": "2016년, 한 상자에 버려진 여덟 마리의 검은 강아지들이 보호소에 왔습니다. 일곱 마리는 가정을 찾았습니다. 가장 큰 한 마리는 아무도 원하지 않아 — 꼬박 일 년을 기다렸습니다. 그의 이름은 Hekthor였습니다.",
  "about.crawl.p2": "어느 날 한 부부가 보호소에 왔습니다, 입양하려던 작은 흰 암컷 Sindy를 보러. 우연히도 그 순간 Hekthor가 Sindy의 우리에 있었습니다 — 자신의 우리가 막 청소 중이었기 때문입니다. 그저 따라왔을 뿐이고, 개를 원한 적 없던 그 남자가, 난생처음 본 검은 개와 사랑에 빠졌습니다.",
  "about.crawl.p3": "일주일 뒤 둘은 함께였고, 아름다운 이야기가 시작되었습니다. 그 남자의 삶 전체가 바뀌었고, 시간이 지나면서 한 가지를 깨달았습니다: 개를 키우고, 개의 사랑이 어떤 것인지 아는 사람만이 진정으로 도움이 필요한 개들을 도울 수 있다고.",
  "about.crawl.p4": "그렇게 Heroglyph이 탄생했습니다 — 전 세계 반려인들을 세상에서 가장 큰 커뮤니티로 하나로 묶기 위한 상징. 우리 자신과 우리 개들, 그리고 다음 세대를 위해 — 개가 단순한 동물이 아니라 우리를 더 나은 인간으로 만들어주는 존재임을 두려움 없이 인정하는 사람들을 위한 커뮤니티.",
  "about.crawl.p5": "지금, 첫 번째 이정표로의 여정이 시작됩니다 — 1,000,000개의 Heroglyph를 만드는 것. 그리고 당신도 그 일부가 될 수 있습니다. 세상을 바꿀 수 있다고 믿을 만큼 충분히 미친 사람들이야말로 실제로 그것을 해내는 사람들이니까.",
  "about.crawl.p6": "개를 믿습니다.",
  "about.timeline.heading": "DOGYPT 이야기",
  "about.milestone.1.year": "2017",
  "about.milestone.1.tag": "보호소",
  "about.milestone.1.title": "보호소 속의 보물",
  "about.milestone.1.body": "아무도 원하지 않던 검은 개가 보호소 울타리 뒤에서 기다리고 있었습니다. 그의 이름은 Hekthor가 되었습니다. 그를 입양한 것은 구조가 아니었습니다 — 그것은 모든 것의 시작이었습니다.",
  "about.milestone.2.year": "2018",
  "about.milestone.2.tag": "유대",
  "about.milestone.2.title": "영원한 유대",
  "about.milestone.2.body": "그는 한마디 말도 없이 내 삶에서 가장 힘든 시기를 함께 견뎌냈습니다. 모든 반려인은 이것을 압니다 — 당신이 무너질 때 정확히 당신을 안아주는 존재.",
  "about.milestone.3.year": "2019",
  "about.milestone.3.tag": "여정",
  "about.milestone.3.title": "책이 된 산책",
  "about.milestone.3.body": "우리는 함께 슬로바키아를 걸었습니다 — 42일, 800킬로미터, 하나의 조용한 약속. 그 길은 책이 되었습니다: 「Cesta s Hrdinom」 — 영웅과 함께한 길.",
  "about.milestone.4.year": "2022",
  "about.milestone.4.tag": "이름",
  "about.milestone.4.title": "반려인들의 나라",
  "about.milestone.4.body": "피라미드, 신비주의, 이집트의 영원한 영광 — 인류는 수천 년간 매혹되었습니다. 개의 무한한 사랑과 결합하면 DOGYPT가 됩니다. 나는 2022년 두바이 엑스포에서 파라오 복장으로 이 아이디어를 확정했습니다.",
  "about.milestone.5.year": "지금",
  "about.milestone.5.tag": "Dogypt",
  "about.milestone.5.title": "여정은 당신과 함께 시작됩니다",
  "about.milestone.5.body": "DOGYPT는 개로 인해 삶이 바뀐 모든 이를 위한 운동입니다. 지구에서 가장 오래되고 가장 솔직한 유대 위에 세워졌습니다. Hekthor는 창립자 #1입니다. 당신이 다음입니다.",
  "about.outro.quoteLead": "그것은 결코",
  "about.outro.quoteTail": "\"그냥 개\"가 아니었습니다.",
  "about.outro.body": "당신은 이미 그 느낌을 압니다 — 개는 소유하는 것이 아니라, <strong>사랑하는 누군가</strong>라는 것을. 이제 그 사랑이 조직되고, 연결되어, <strong>무언가를 바꿀 만큼 강력해진다면.</strong> 그것이 바로 <strong>DOGYPT</strong>가 존재하는 이유입니다.",
  "about.outro.name1": "Matej",
  "about.outro.and": "와",
  "about.outro.name2": "Hekthor",
  "about.outro.cta": "도깁트인 되기",
  "about.reel.prev": "이전 사진",
  "about.reel.next": "다음 사진",
