  "religion.hook.doglovers": "반려인들은?",
  "religion.hook.worship": "우리의 개를 숭배합시다.",
  "religion.cta": "도깁트인 되기",
  "religion.aria.question": "질문",
  "religion.aria.preamble": "서문",
  "religion.aria.sacredIndex": "신성한 목록",
  "religion.aria.scrollDown": "아래로 스크롤",
  "religion.preamble.headlineGrad": "개를 믿어요",
  "religion.preamble.headlineLine": "우리는",
  "religion.preamble.text": "우리, 반려인들의 나라 — 지구상 모든 개의 <strong>무한한 충성심</strong>, <strong>진정한 사랑</strong>과 <strong>순수한 영혼</strong>을 알기에 — 인간 사회에서 개의 지위를 높이고, 그들을 위한 <strong>커뮤니티</strong>를 만들고, 그들의 삶을 <strong>개선</strong>하며, 도움이 필요한 모든 개의 운명을 <strong>다시 쓰기</strong> 위해, 우리 스스로에게 이 헌법을 부여합니다.",
