  "wall.hero.taglineGod": "개는 신이다.",
  "wall.hero.cta": "도깁트인 되기",
  "wall.hero.total": "1,000,000",
  "wall.hero.dogs": "개",
  "wall.hektor.msg": "Hekthor, 너는 나의 가장 위대한 영웅이고, 가장 좋은 친구이며, 충실한 동반자이고, 가차 없는 스승이야 — 너는 내 인생에서 가장 아름다운 이야기야. 너 덕분에 나는 개의 종교를 세웠고, 내 사랑이 조금도 특별하지 않다는 걸 깨달았어 — 개를 한 번이라도 사랑해 본 사람이라면 누구나 마음속으로 똑같은 것을 느끼거든. 우리가 함께한 최고의 삶에 고마워. 사랑해.",
  "wall.info.title": "백만 마리의 개.<br/>우리가 해낼 수 있을까요?",
  "wall.info.body": "DOGYPT는 반려인들을 위한 운동입니다. 모든 개는 고유한 Heroglyph를 얻습니다 — 글로벌 무리 안에서의 영구적인 자리. 우리는 백만 마리의 영웅을 모으고 있습니다. 가장 먼저 함께하세요.",
