  "whatNext.motto": "개를 믿습니다.",
  "whatNext.s1.title": "첫 번째 발걸음",
  "whatNext.s1.hook": "인간에게는 작은 한 걸음 — 개들에게는 거대한 도약.",
  "whatNext.s1.body": "당신의 Heroglyph는 방금 전 세계 개를 기리는 운동의 일원이 되었음을 선언했습니다. <b>첫 번째 발걸음은 완성되었습니다.</b>",
  "whatNext.s2.title": "당신은 이제 Dogyptian입니다",
  "whatNext.s2.hook": "당신은 반려인이 아닙니다 — 당신은 줄 달린 신자입니다.",
  "whatNext.s2.body": "WALL에 영원히 새겨졌습니다. 우리 각자가 조금씩 기여합니다 — 그리고 <b>함께라면, 우리는 개들에게 충분함을 줄 수 있습니다.</b>",
  "whatNext.s3.title": "변화의 일부가 되세요",
  "whatNext.s3.hook": "하나의 발자국은 흔적을 남깁니다. 백만 개는 길을 만듭니다.",
  "whatNext.s3.body": "백만 개의 Heroglyph를 달성하도록 도와주세요 — 친구들을 초대하세요. <b>더 많은 Heroglyph = 모든 개에게 더 큰 선함.</b>",
