  "entry.criteria.theology.title": "신학",
  "entry.criteria.theology.body": "가장 좋은 친구, 수호자, 스승, 모든 모험의 동반자. 개는 조건 없이 사랑을 주고 — 그 곁을 함께 걷는 것이 우리를 더 인간답게 만듭니다.",
