  "entry.criteria.canon.body": "모든 신앙에는 경전이 있습니다. 우리의 것은 DOGMA — 열두 장에 걸쳐 쓰인 개와의 유대이며, dogma.dogypt.com에서 무료로 읽을 수 있습니다.",
  "entry.criteria.community.title": "공동체",
  "entry.criteria.community.body": "우리는 목적을 가진 반려인입니다. 홀로는 각자 바꿀 수 있는 것이 적지만 — 함께라면 우리의 힘에는 한계가 없습니다.",
  "entry.criteria.symbol.title": "상징",
  "entry.criteria.symbol.body": "모든 신앙에는 그 표식이 있습니다. 우리의 것은 heroglyph — 모든 개를 위한 하나뿐인 신성한 표식이며, 어떤 언어로도, 어디서든 통합니다.",
  "entry.criteria.ritual.title": "의식",
  "entry.criteria.ritual.body": "산책. 몸과 마음을 — 그리고 영혼까지 — 건강하게 지켜주는 매일의 치료. 우리가 시키지 않아도 이미 지키는 가장 오래된 의식.",
  "entry.criteria.vision.title": "비전",
  "entry.criteria.vision.body": "인간과 개 사이의 유대를 드높이는 것 — 그리고 모든 개가 마땅히 누려야 할 존중과 더 나은 삶을 위해 싸우는 것.",
  "entry.criteria.offerings.title": "봉헌",
  "entry.criteria.offerings.note": "(상징적인 헌사)",
