  "entry.criteria.offerings.tag": "100% 투명성",
  "entry.criteria.offerings.body": "€11, 단 한 번. 상징적인 봉헌 — 모든 수입과 모든 지출은 누구에게나 열린 장부에 기록됩니다. 우리를 살아 숨 쉬게 하는 에너지입니다.",
