  "heroglyph.flow.more.ainubis.d": "우리의 맞춤형 AI, 당신의 조력자이자 멘토예요. 반려견을 속속들이 알고 있어요. 그 자료로 배우고, 들여다보고, 당신의 자료와 경험도 더할 수 있어요.",
  "heroglyph.flow.more.ainubis.t": "AINUBIS",
  "heroglyph.flow.more.cause.d": "DOGYPT는 반려인의 삶을 편하게 해 줄 뿐 아니라, 좋은 사람들을 모으고 도움이 필요한 개들을 투명하게 도와요. DOGYPT의 창립자 HEKTHOR도 보호소 출신이에요.",
