  "heroglyph.flow.more.dogid.d": "반려견의 모든 프로필을 한곳에. 입력한 정보는 AINUBIS가 활용해요. 동물병원 같은 곳에서 바로 꺼내 볼 수 있는 든든한 ‘성적표’예요.",
  "heroglyph.flow.more.dogid.t": "DOG ID",
  "heroglyph.flow.more.dogtrip.d": "전 세계 반려견 동반 모험을 한곳에. 좋아하는 나들이를 추가하고 무리와 나눠 보세요. 다른 사람들에게 영감을 얻고, 포인트와 배지, 레벨을 모아 보세요.",
  "heroglyph.flow.more.dogtrip.t": "DOGTRIP",
  "heroglyph.flow.more.eyebrow": "DOGYPT 멤버십",
  "heroglyph.flow.more.glyph.d": "반려견을 완벽하게 담아낸 고유한 상징. 반려인을 하나로 잇는 만국 공통어. DOGYPT로 들어가는 열쇠예요.",
  "heroglyph.flow.more.glyph.t": "HEROGLYPH",
  "heroglyph.flow.more.money.d": "€11 중 €5는 개발에, €3는 커뮤니티에, €2는 개 구조에, €1은 Hekthor의 밥그릇에 들어가요. 모든 지출은 기록되고 공개돼요.",
  "heroglyph.flow.more.money.t": "돈은 어디로 갈까요",
