  "heroglyph.flow.more.pack.d": "반려인을 위해 만든 플랫폼에 접속할 수 있어요. 앱은 계속 자라나며 모든 면에서 반려인에게 도움이 될 거예요.",
  "heroglyph.flow.more.pack.t": "회원 전용 공간",
  "heroglyph.flow.more.prev": "이전",
  "heroglyph.flow.more.sniffer.d": "여행, 정기 산책, 로드트립 모험을 함께할 친구, 커플, 그룹을 찾아보세요. 개와 보호자를 위해 특별히 만든 매칭 서비스예요.",
  "heroglyph.flow.more.sniffer.t": "SNIFFER",
  "pack.buddy.intro": "함께 세상을 킁킁 탐험할 친구를 찾아보세요.",
  "heroglyph.flow.stay.done.cta": "WALL 보기",
  "heroglyph.flow.stay.done.guest": "AINUBIS가 사진을 확인하면, 몇 분 뒤 반려견이 WALL에 올라가요. heroglyph는 보관해 둘게요 — 언제든 함께할 수 있어요.",
  "heroglyph.flow.stay.done.support": "후원해 주셔서 감사해요. AINUBIS가 사진을 확인하면, 몇 분 뒤 반려견이 메시지와 함께 WALL에 올라가요.",
