  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. 무리 안에서: 다른 멤버가 보는 것",
  "privacy.s12.body": "제3조는 공개된 GodsGrid에 대해 설명해요. 무리 안쪽 — 멤버 전용 구역 — 에서는 로그인한 다른 멤버들이 더 많이 볼 수 있어요: 당신의 이름, 도깁트 번호, 반려견의 이름과 사진, 당신이 입력한 반려견의 속성, 기록하거나 공개한 여행, 당신의 평가와 댓글, 그리고 프로필에 적은 모든 것이요. 이메일 주소, 우편 주소, 결제 정보, 다른 사람과의 메시지는 보이지 않아요. 여행을 공개로 설정하면 경로, 날짜, 반려견이 모든 멤버에게 보이고 참여를 요청할 수 있게 돼요 — 공개한다는 건 그런 뜻이에요. 비공개로 둔 여행은 당신과 이미 함께하는 사람만 볼 수 있어요. 둘 중 무엇으로 할지는 당신이 선택하고, 언제든 바꿀 수 있어요.",
  "privacy.s13.title": "13. 메시지와 신고",
  "privacy.s13.body": "멤버 간의 개인 메시지는 세션이 끝나도 대화가 남도록 저희 데이터베이스(Supabase)에 저장돼요. 법적 근거: GDPR 제6조 제1항 (b) — 당신이 지불한 멤버십의 일부예요. 저희는 이를 일상적으로 읽지 않고, 광고나 프로파일링에 사용하지 않아요. 대화를 열어보는 경우는 신고가 들어왔을 때, 구체적인 악용이나 보안 사고를 조사할 때, 또는 법으로 요구될 때뿐이에요. 신고는 당신이 고른 이유, 선택적으로 남긴 메모, 그리고 신고 대상에 대한 참조만 저장해요 — 별도의 복사본은 저장하지 않아요. 차단은 멤버 식별자 쌍으로 저장돼요. 계정을 삭제하면 당신의 메시지도 함께 사라져요. 상대방 대화창에 남는 복사본은 삭제된 멤버로부터 온 것으로 표시돼요 — 그 대화는 상대방의 것이기도 하니까요.",
  "terms.s12.title": "12. 당신이 게시하는 콘텐츠",
  "terms.s12.body": "HEROGLYPH와 함께, 무리 안에서 콘텐츠를 게시할 수 있어요: 여행 사진, 경로와 장소, 여행 설명, 평가, 댓글과 질문, 그리고 프로필에 적는 모든 것이요. 여행을 '다녀왔음'으로 표시하면 다른 멤버들이 당신의 이름과 함께 다녀온 개들을 볼 수 있어요. 당신이 게시한 모든 것의 소유권은 당신에게 남아요. 게시함으로써 당신은 DOGYPT s.r.o.에 서비스 운영과 홍보를 위해 해당 콘텐츠를 저장, 표시, 가공할 수 있는 전 세계적이고 무상이며 비독점적인 라이선스를 부여해요 — 예를 들어 지도, 여행 목록, 공유 카드에 여행 사진을 보여주는 것이요. 이 라이선스는 콘텐츠가 서비스에 있는 동안 유지돼요. 콘텐츠나 계정을 삭제하면 끝나지만, 백업은 정상적인 주기에 따라 만료될 때까지 남아요. 저희는 당신의 콘텐츠를 판매하지 않고, 다른 사람의 자체 사용을 위해 라이선스를 주지도 않아요. 게시할 권리가 있는 것만 게시해 주세요 — 다른 사람이 찍은 사진이나 그 사진에서 식별 가능한 사람들도 포함돼요.",
  "terms.s13.title": "13. 멤버 간 메시지",
  "terms.s13.body": "멤버들은 서로 직접 메시지를 보낼 수 있어요. 메시지는 참여자 간에 비공개예요 — 저희는 일상적으로 읽지 않고, 광고에 사용하지도 않아요. 다시 돌아왔을 때 대화가 남아 있도록 서버에 저장되며, 다음 세 가지 경우에 대화를 읽을 수 있어요: 누군가 신고했을 때, 구체적인 악용이나 보안 사고를 조사할 때, 법으로 요구될 때요. 다른 멤버는 언제든 차단할 수 있어요. 차단은 즉시, 양방향으로 적용돼요. 메시지는 다른 온라인 대화와 똑같이 다루어 주세요 — 결제 정보, 비밀번호, 저장되길 원치 않는 문서는 보내지 마세요.",
  "terms.s14.title": "14. 신고와 모더레이션",
  "terms.s14.body": "프로필, 여행, 대화는 신고할 수 있어요. 신고는 저희에게 전달되고 사람이 직접 읽어요 — 지금은 창립자 Matej Stacho예요. 모든 신고를 7일 이내에 확인하는 걸 목표로 해요. 발견한 내용에 따라 아무 조치를 하지 않거나, 콘텐츠를 삭제하거나, 멤버에게 경고하거나, 게시할 수 있는 내용을 제한하거나, 계정을 닫을 수 있어요. 당신의 콘텐츠에 조치를 취하면 이메일로 이유를 알려드리고, 답장으로 이의를 제기할 수 있어요. 제7조를 위반하는 경우 저희 자체 판단으로 콘텐츠를 삭제할 수도 있어요. 고의적이거나 반복적인 악용 — 괴롭힘, 스팸, 가짜 여행, 미성년자 관련 콘텐츠 — 는 추가 경고 없이 계정을 종료시켜요.",
  "dogPage.bonesForDog": "이 페이지로 가입하면 {dog}가 20 BONES를 받아요.",
  "dogPage.bonesNote": "BONES는 DOGYPT의 화폐예요 — 보호자의 계정으로 들어가요.",
  "dogPage.invitedBy": "{name}이(가) 당신을 DOGYPT로 초대해요",
  "dogPage.invitedByFallback": "당신은 DOGYPT에 초대받았어요",
  "heroglyph.flow.photo.skip": "사진은 나중에 추가할게요",
  "heroglyph.flow.name.uniqueLine": "그 이름은 수천 마리의 개가 함께 쓰고 있어요. 하지만 이 상징을 함께 쓰는 개는 없어요.",
  "heroglyph.flow.name.alert": "이 이름은 세상의 수천 마리 개가 가지고 있어요.",
  "heroglyph.flow.name.nextCta": "다음",
  "heroglyph.flow.name.createCta": "Heroglyph 만들기",
