  "pack.cal.life.srcNone": "평균 기대 수명: 아직 견종이나 체중을 모르기 때문에, 중형 등급을 기준으로 추정해요. DOG ID에 견종을 추가하세요.",
  "pack.cal.life.srcPre": "평균 기대 수명:",
