  "pack.cal.life.srcWeight": "체중 기반 추정",
  "pack.cal.life.bandNote": "이건 수천 마리 개의 평균일 뿐, 이 아이에 대한 예측은 아니에요.",
  "pack.cal.life.srcRefBreed": "출처: 견종 클럽이 발표한 범위 (AKC / The Kennel Club).",
  "pack.cal.life.srcRefWeight": "출처: 체중별 수의학 기대 수명 조사 (UK VetCompass / RVC life tables).",
  "pack.cal.life.tgtPre": "목표:",
  "pack.cal.life.tgtBody": "홀리스틱 케어로 더할 수 있는 최대 5년 — 체형 유지, 야외 활동, 치아, 수면, 그리고 불필요한 약물을 최소화하는 것.",
  "pack.cal.life.tgtSrc": "대략적인 추정일 뿐, 약속은 아니에요. 그중 측정된 건 딱 하나예요: 체형 유지만으로도 래브라도의 수명이 1.8년 늘었어요 (Purina Life Span Study, JAVMA 2002).",
  "pack.cal.life.intro": "아래는 반려견의 전체 생애를 블록으로 표현한 거예요. 한 블록 = 1주, 한 줄 = 1년. 한편으로는 조금 섬뜩하지만, 다른 한편으로는 매 순간을 소중히 여기고 미루지 말아야 한다는 바로 그 깨달음이에요.",
  "pack.cal.life.fromBirth": "출생일부터 계산",
