  "pack.cal.life.tip.weight.title": "체형 유지만이 증명된 사실이에요",
  "pack.cal.life.tip.weight.body": "개를 위해 할 수 있는 모든 것 중, 수명에 대해 가장 확실한 증거가 있는 건 딱 하나예요: 체중이 늘지 않게 하는 거예요. 슬림한 개와 살짝 과체중인 개의 차이는 몇 달이 아니라 몇 년이에요. 누르지 않아도 갈비뼈가 만져져야 해요.",
  "pack.cal.life.tip.move.title": "동네 한 바퀴가 아니라 진짜 지형에서의 운동",
  "pack.cal.life.tip.move.body": "울퉁불퉁한 땅은 관절, 근육, 그리고 머리를 활발하게 유지해줘요. 당신이 기록하는 여행 하나하나가 이 그리드에서 짙은 색의 한 주가 돼요 — 그리고 짙은 주의 개수는 당신이 실제로 영향을 줄 수 있는 유일한 것이에요.",
  "pack.cal.life.tip.food.title": "개가 음식이라고 알아보는 음식",
  "pack.cal.life.tip.food.body": "원재료와 밥그릇 사이의 단계가 적을수록, 중간에 잘못될 수 있는 것도 줄어들어요. 사료가 죄는 아니지만, 식단도 아니에요 — 지름길이에요.",
  "pack.cal.life.tip.chem.title": "정말 필요할 때만 약을 써요",
  "pack.cal.life.tip.chem.body": "연중 내내 하는 구충제, 편의를 위한 마취, '혹시 몰라서' 쓰는 항생제는 습관이 아니라 결정이에요. 하나하나마다 물어보세요: 안 하면 어떻게 될까? 답이 '아무 일도 없다'면, 하지 마세요.",
  "pack.cal.life.tip.stress.title": "휴식도 운동만큼 중요해요",
  "pack.cal.life.tip.stress.body": "늘 경계 상태인 개는 몸을 안에서부터 소모시켜요. 방해받지 않는 잠, 예측 가능한 하루, 활동 후의 조용함은 게으름이 아니에요 — 몸이 스스로를 회복하는 시간이에요.",
  "pack.cal.life.tip.protocol.title": "허둥지둥 병원으로 달려가는 대신 프로토콜을",
  "pack.cal.life.tip.protocol.body": "구충, 분변 검사, 혈액 검사는 캘린더에 각자의 기간이 있어요. 1년에 두 번 혈액을 확인하는 개는 치료받는 게 아니라 — 미리 대비하고 있는 거예요.",
  "pack.cal.life.tip.joints.title": "관절은 아프기 전에 미리 돌봐요",
  "pack.cal.life.tip.joints.body": "당신의 개는 지금 시니어 단계예요. 관절 케어 기간은 캘린더에서 11월부터 시작돼요 — 다리를 절어서가 아니라, 절지 않게 하기 위해서예요.",
