  "pack.join.sentTitle": "메일함을 확인하세요",
  "pack.join.sentBody": "{masked}로 링크를 보냈어요. 탭 한 번으로 무리에 들어올 수 있어요. 링크는 한 번만 작동해요.",
  "pack.join.wrongTitle": "이 초대는 다른 주소에 속해 있어요",
