  "pack.nature.el.fire": "불",
  "pack.nature.el.fire.of": "불의",
  "pack.nature.el.fire.summary": "파티의 주인공 — 시끄럽고 애정이 많고, 관심받아야 하고, 그리고 **쉽게 꺼지지 않아요**.",
  "pack.nature.el.fire.trait0": "누구에게나 몇 년 만에 만난 듯 인사해요 — **그 큰 소리는 흥분이 아니라 기본값이에요**",
  "pack.nature.el.fire.trait1": "순식간에 솟아오르고, **가라앉는 데 한 시간이 걸려요**",
  "pack.nature.el.fire.trait2": "시원한 곳을 찾아다녀요: 타일 바닥, 그늘, 문 아래 바람",
  "pack.nature.el.fire.trait3": "얕게 자고, 자면서도 움직이며, **작은 소리에도 깨요**",
  "pack.nature.el.fire.trait4": "한 번에 금방 익히고 — 반복하지 않으면 **똑같이 빨리 잊어버려요**",
  "pack.nature.el.fire.food0": "**더 담백하고 체온을 식히는 단백질을** — 토끼, 칠면조, 흰 살 생선이 양고기나 사슴고기보다 잘 맞아요",
  "pack.nature.el.fire.food1": "**그릇뿐 아니라 음식 자체에 수분을** — 마른 사료에 육수나 물을 조금 뿌리는 게 가장 간단한 방법이에요",
  "pack.nature.el.fire.food2": "여름은 **이 아이의 계절** — 식욕은 줄고 불안정함은 늘어요. 둘 다 같은 시기에 지켜볼 만해요",
  "pack.nature.el.fire.avoid0": "**더운 달에 먹이는 무겁고 몸을 데우는 고기** — 양고기, 사슴고기, 오리고기",
  "pack.nature.el.fire.avoid1": "**격한 놀이 전후 가득 찬 밥그릇** — 그 사이에 한 시간은 비워두세요",
  "pack.nature.el.fire.avoid2": "**차갑게 누울 곳이 없는 방**",
  "pack.nature.el.fire.body": "단단하고 탄탄한 몸, 작은 머리, **잠을 얕게 자요**, 차가운 타일과 그늘을 찾아요.",
  "pack.nature.el.fire.watch": "과열, 빠른 심박수, **밤의 불안정함**, 혼자 남으면 불안해해요. 약점은 심장과 혈액순환에 있어요.",
  "pack.nature.el.fire.facts.season": "여름",
  "pack.nature.el.fire.facts.organs": "심장 · 소장",
  "pack.nature.el.fire.facts.emotion": "기쁨 — 그리고 그걸 어떻게 해야 할지 모름",
  "pack.nature.el.fire.facts.taste": "쓴맛",
  "pack.nature.el.fire.facts.colour": "빨강",
  "pack.nature.el.earth": "흙",
  "pack.nature.el.earth.of": "흙의",
  "pack.nature.el.earth.summary": "차분하고, 충실하고, 엄마 같아요 — 그리고 **밥그릇을 위해 살아요**.",
  "pack.nature.el.earth.trait0": "**음식이 하루의 중심이에요.** 그 외엔 뭐든 협의 가능해요",
  "pack.nature.el.earth.trait1": "어디서든 1분 안에 자리를 잡고, **다시 옮겨지길 원하지 않아요**",
  "pack.nature.el.earth.trait2": "**집안의 분위기를 배 속에 담고 다녀요** — 긴장된 한 주는 부드러운 변으로 나타나요",
  "pack.nature.el.earth.trait3": "느리고 신중해요; **서두르게 하는 게 오히려 더 손해예요**",
  "pack.nature.el.earth.trait4": "강아지, 아이들, 그리고 남의 문제에도 엄마 같아요",
  "pack.nature.el.earth.food0": "**눈대중이 아니라 저울로 먹이를 재세요.** 흙의 개는 매일 '한 번도 밥을 못 먹었다'고 당신을 설득할 거예요",
  "pack.nature.el.earth.food1": "**한 번의 큰 식사보다 두세 번의 작은 식사** — 빈속이 다른 개보다 이 아이를 더 불안하게 해요",
  "pack.nature.el.earth.food2": "**실온이거나 살짝 데운 것**, 냉장고에서 바로 꺼낸 건 피하세요",
  "pack.nature.el.earth.avoid0": "**하루 종일 꺼내둔 밥그릇** — 자율 급식은 이 아이가 반응하는 유일한 체계를 빼앗아요",
  "pack.nature.el.earth.avoid1": "**간식을 대화 수단으로 쓰는 것.** 그 '화폐'를 배우고 거래를 시작할 거예요",
  "pack.nature.el.earth.avoid2": "**기름진 식탁 찌꺼기** — 위장이 약점이고 빠르게 반응해요",
  "pack.nature.el.earth.body": "둥글고 큰 몸, 큰 머리, **느리고 신중한 움직임**, 어디서든 편히 쉬어요.",
  "pack.nature.el.earth.watch": "소화, 식욕 기복, **체중**, 치아와 잇몸. 약점은 위와 장에 있어요.",
  "pack.nature.el.earth.facts.season": "늦여름",
  "pack.nature.el.earth.facts.organs": "비장 · 위",
