  "pack.nature.intro.title": "당신의 개는 누구인가요?",
  "pack.nature.intro.body": "스물두 개의 질문과 하나의 체크리스트. 반려견이 무엇으로 이루어졌는지, 가족을 위해 어떤 역할을 하는지, 지금 균형이 어디로 기울어 있는지 알게 돼요.",
