  "pack.nature.balance.body": "반려견의 체질은 평생 정해져 있지만, 균형은 흐트러질 수 있어요. 해당되는 걸 체크하세요 — 원하는 만큼, 아무것도 없어도 괜찮아요.",
  "pack.nature.balance.none": "목록에 없나요? 비워두고 계속하세요 — 그게 가장 좋은 답이에요.",
  "pack.nature.progress": "진행 상황",
