  "pack.nature.ans.sometimes": "때때로",
  "pack.nature.ans.no": "아니요",
  "pack.network.ads.body": "유료 광고는 새로운 반려인을 찾는 데 매우 비효율적인 방법이에요 — 그리고 우리 돈을 큰 기업에 던지는 거예요. 운동의 멤버들에게 활동에 대해 직접 보상하는 게 훨씬 더 효과적이에요. 단 하나 조건이 있어요: <strong style=\"font-weight:600\">진짜로 효과가 있는 건 당신이 직접 나서서 주변 사람들에게 우리 이야기를 할 때뿐이에요</strong> :)",
  "pack.network.ads.header": "왜 이 방식인가요?",
  "pack.network.ads.wordAd": "광고",
  "pack.network.ads.wordScroll": "낯선 사람이 그냥 스크롤해서 지나가요",
