  "pack.network.back": "뒤로",
  "pack.network.bonesLabel": "당신의 BONES",
  "pack.network.bonesRate": "{n} BONES = 1€",
  "pack.network.bonesUnit": "bones",
  "pack.network.capHintLog": "상한 1:1 — 선물은 당신이 이미 살아온 만큼만 맞춰줄 수 있어요.",
  "pack.network.capHintRow": "상한 1:1 — 선물은 당신이 살아온 만큼을 맞춰줘요",
  "pack.network.capped.none": "이 송금으로는 헌신이 없어요 — 당신의 선물은 이미 당신이 살아온 모든 것과 맞아요. BONES는 그래도 전달돼요. <i>돈은 시간을 두 배로 늘려줄 순 있지만, 절대 그것을 대신하지 못해요.</i>",
  "pack.network.capped.room": "<b style=\"color:#2a1608\">{room}</b>으로 제한됨 — 선물은 당신이 살아온 만큼만 맞출 수 있어요 (지금까지 헌신 {lived}). BONES는 그래도 전달돼요; 명예는 그 날들을 기다려요.",
