  "pack.network.confirmSend": "확실한가요? 보내면 BONES는 당신의 잔액에서 빠져나가요 — 되돌릴 수 없어요.",
  "pack.network.copyLinkAria": "초대 링크 복사",
  "pack.network.devotionWord": "헌신",
  "pack.network.emptyLine": "아직 아무도 없어요 — 여기 적힐 첫 이름이 당신 계보의 시작이에요.",
  "pack.network.eyebrow": "DOGYPT는 당신 덕분에 성장해요",
  "pack.network.generatingLink": "링크를 생성하는 중…",
  "pack.network.linkFailed": "초대 링크를 불러올 수 없었어요.",
  "pack.network.linkRetry": "다시 시도",
  "pack.network.groupDirect": "직접",
  "pack.network.groupTheirBrings": "그들이 데려온 사람들",
  "pack.network.inLine": "당신의 계보에서",
  "pack.network.info.bones.body": "BONES는 DOGYPT의 내부 화폐예요 — 실제 존재하는 것을 위한 장난스러운 이름이에요. 개는 뼈로 지불하고, 우리도 그래요. 반려인을 무리로 데려오고 운동을 앞으로 나아가게 함으로써 <b>벌고</b>, DOGYPT 안에서 <b>써요</b>: 보호소 모금을 지원하거나, 굿즈를 받거나, 나중에는 다른 도깁트인들이 만든 것에 지불하면서요. <b>{n} BONES = 1€.</b>",
  "pack.network.info.bones.cap": "BONES가 뭐예요?",
  "pack.network.info.why.body": "이 정도 규모의 운동은 돈으로 살 수 없어요 — 어떤 예산도 낯선 사람에게 도깁트인이 친구에게 닿는 것처럼 닿을 수 없어요. 그래서 무리는 닿을 수 있는 곳 — 바로 당신 — 에 보상을 둬요. 누군가 당신의 링크로 합류하면 <b>{l1} BONES</b>를 받아요; 그 사람이 또 누군가를 데려오면 <b>{l2}</b>를 더 받아요. 말을 퍼뜨리는 모든 도깁트인은 영업 사원이 아니라 — 전도사이고, 우리는 그 일을 존중해요.",
  "pack.network.info.why.cap": "당신에게 부탁하는 이유",
  "pack.network.intro": "운동은 멤버들이 메시지를 전하고 새로운 사람을 데려올 때만 성장해요. 그래서 당신에게 직접 부탁해요: <strong style=\"color:#2a1608;font-weight:600\">당신이 아는 반려인들을 초대하세요</strong>. 정확히 어떻게 작동하는지 알려드릴게요.",
