  "pack.network.step1Title": "링크 공유하기",
  "pack.network.step2Body": "누군가 당신의 링크로 <strong style=\"color:#2a1608;font-weight:600\">Heroglyph</strong>를 만들면, 당신은 <strong style=\"color:#2a1608;font-weight:600\">{l1} BONES</strong>를 받아요. 그 멤버가 또 누군가를 데려오면, 그 사람은 {l1}을 받고 <strong style=\"color:#2a1608;font-weight:600\">당신은 {l2}를 더</strong> 받아요.",
